settings.custom_code:
{% assign comparison = product.metafields.custom.driver_comparison.value %}

{% if comparison %}
  {% assign cards = comparison.driver_comparison_card.value %}
  {% if cards == blank %}
    {% assign cards = comparison.driver_comparison_card %}
  {% endif %}

  <style>
    /*
     * SECTION WRAPPER
     * Consistent top margin with other spec components on the page.
     */
    .iron-comparison {
      margin-top: 48px;
    }

    /*
     * SCROLL CONTAINER
     * Refined scrollbar — minimal and unobtrusive.
     */
    .iron-comparison__scroll {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    .iron-comparison__scroll::-webkit-scrollbar { height: 4px; }
    .iron-comparison__scroll::-webkit-scrollbar-thumb { background: #ccc; border-radius: 999px; }
    .iron-comparison__scroll::-webkit-scrollbar-track { background: transparent; }

    /*
     * CARD GRID
     * align-items: start prevents cards from stretching to match
     * each other — fixes uneven row heights when content varies.
     */
    .iron-comparison__grid {
      display: flex;
      gap: 16px;
      padding-bottom: 8px;
      align-items: start;
    }

    @media screen and (min-width: 990px) {
      .iron-comparison__grid {
        justify-content: center;
      }
    }

    /*
     * CARD
     * Defined width, hairline border, no radius — architectural and clean.
     */
    .iron-comparison__card {
      flex: 0 0 280px;
      display: flex;
      flex-direction: column;
      border: 1px solid #e8e8e8;
    }

    /*
     * TITLE IMAGE AREA
     * Black header band — compact brand anchor.
     */
    .iron-comparison__title-image {
      background: #000;
      padding: 10px 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 44px;
    }

    .iron-comparison__title-image img {
      max-width: 50%;
      max-height: 100%;
      height: auto !important;
      width: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /*
     * PRODUCT IMAGE AREA
     * Neutral grey field, fixed height keeps cards visually aligned.
     */
    .iron-comparison__product-image {
      background: #f2f2f2;
      padding: 24px;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 220px;
    }

    .iron-comparison__product-image img {
      max-width: 100%;
      max-height: 100%;
      height: auto !important;
      width: auto !important;
      object-fit: contain !important;
      display: block;
    }

    /*
     * DESCRIPTION
     * Increased to 14px for comfortable reading.
     * Min-height keeps cards aligned when copy length varies.
     */
    .iron-comparison__description {
      padding: 16px 20px;
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 14px;
      line-height: 1.7;
      color: #444;
      letter-spacing: 0.01em;
      min-height: 80px;
      border-bottom: 1px solid #e8e8e8;
    }

    /*
     * RATINGS BLOCK
     * Flush to card edges, contained by card outline.
     */
    .iron-comparison__ratings {
      flex: 1;
    }

    /*
     * RATING ROWS
     * Increased padding and font sizes for legibility.
     * Same alternating + hover treatment as spec tables.
     */
    .iron-comparison__rating-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      align-items: center;
      padding: 14px 20px;
      border-bottom: 1px solid #e8e8e8;
      column-gap: 12px;
      transition: background 0.18s ease, box-shadow 0.18s ease;
    }

    .iron-comparison__rating-row:nth-child(odd)  { background: #fff; }
    .iron-comparison__rating-row:nth-child(even) { background: #fafafa; }

    .iron-comparison__rating-row:last-child {
      border-bottom: none;
    }

    .iron-comparison__rating-row:hover {
      background: #f2f2f2;
      box-shadow: inset 3px 0 0 #000;
    }

    /*
     * RATING LABEL
     * Bumped to 11px — readable without overpowering the value.
     */
    .iron-comparison__rating-label {
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: #000;
      white-space: nowrap;
    }

    /*
     * RATING VALUE
     * Bumped to 13px — clear hierarchy over label, easy to read.
     */
    .iron-comparison__rating-value {
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 13px;
      font-weight: 400;
      letter-spacing: 0.02em;
      color: #222;
      text-align: right;
      white-space: normal;
      word-break: break-word;
      overflow-wrap: anywhere;
      line-height: 1.4;
    }

    /*
     * RESPONSIVE
     * Cards shrink slightly on mobile; padding pulled in to match
     * spec table mobile treatment.
     */
    @media (max-width: 768px) {
      .iron-comparison__card {
        flex: 0 0 260px;
      }

      .iron-comparison__rating-row {
        padding: 12px 14px;
      }

      .iron-comparison__rating-label { font-size: 10px; }
      .iron-comparison__rating-value { font-size: 12px; }

      .iron-comparison__description {
        padding: 14px 16px;
        font-size: 13px;
      }
    }
  </style>

  <section class="iron-comparison">
    <div class="iron-comparison__scroll">
      <div class="iron-comparison__grid">

        {% for card in cards %}
          <div class="iron-comparison__card">

            {% if card.title_image %}
              <div class="iron-comparison__title-image">
                {{ card.title_image | image_url: width: 600 | image_tag: loading: 'lazy' }}
              </div>
            {% endif %}

            {% if card.product_image %}
              <div class="iron-comparison__product-image">
                {{ card.product_image | image_url: width: 900 | image_tag: loading: 'lazy' }}
              </div>
            {% endif %}

            {% if card.description != blank %}
              <div class="iron-comparison__description">
                {{ card.description }}
              </div>
            {% else %}
              <div class="iron-comparison__description"></div>
            {% endif %}

            <div class="iron-comparison__ratings">
              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Spin</span>
                <span class="iron-comparison__rating-value">{{ card.spin }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Launch</span>
                <span class="iron-comparison__rating-value">{{ card.launch }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Flight Bias</span>
                <span class="iron-comparison__rating-value">{{ card.flight_bias }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Forgiveness</span>
                <span class="iron-comparison__rating-value">{{ card.forgiveness }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Swing Speed</span>
                <span class="iron-comparison__rating-value">{{ card.swing_speed }}</span>
              </div>

              <div class="iron-comparison__rating-row">
                <span class="iron-comparison__rating-label">Weight Adjustment</span>
                <span class="iron-comparison__rating-value">{{ card.weight_adjustment }}</span>
              </div>
            </div>

          </div>
        {% endfor %}

      </div>
    </div>
  </section>
{% endif %}

{% assign spec_table = product.metafields.custom.driver_spec_table.value %}
{% if spec_table %}
<style>
  /*
   * WRAPPER
   * Generous top margin creates breathing room from surrounding content.
   * Overflow-x retained for responsive safety.
   */
  .spec-table-wrapper {
    overflow-x: auto;
    margin-top: 48px;
    -webkit-overflow-scrolling: touch;
  }

  /*
   * TABLE BASE
   * Collapsed borders, refined font stack, base tracking cascades down.
   */
  .spec-table {
    width: 100%;
    border-collapse: collapse;
    font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 12px;
    letter-spacing: 0.04em;
    color: #111;
  }

  /*
   * HEADER ROW
   * All-caps, wide tracking, medium weight — premium catalog aesthetic.
   * Black background anchors the table visually.
   */
  .spec-table thead tr {
    background: #000;
    border-bottom: 2px solid #000;
  }

  .spec-table th {
    background: #000;
    color: #fff;
    padding: 14px 20px;
    text-align: left;
    font-weight: 500;
    font-size: 12px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  .spec-table th:first-child { padding-left: 24px; }
  .spec-table th:last-child  { padding-right: 24px; }

  /*
   * BODY CELLS
   * Generous vertical padding for breathing room. Light border guide.
   * First-child label cells elevated to create spec-name vs value hierarchy.
   */
  .spec-table td {
    padding: 14px 20px;
    border-bottom: 1px solid #e8e8e8;
    color: #222;
    vertical-align: middle;
    white-space: nowrap;
    transition: color 0.2s ease;
  }

  .spec-table td:first-child {
    padding-left: 24px;
    font-weight: 600;
    color: #000;
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .spec-table td:last-child { padding-right: 24px; }

  /*
   * ALTERNATING ROW TREATMENT
   * Near-imperceptible warm grey vs white — whispers structure, not spreadsheet.
   */
  .spec-table tbody tr:nth-child(odd)  { background: #fff; }
  .spec-table tbody tr:nth-child(even) { background: #fafafa; }

  /*
   * HOVER STATE
   * Inset left-edge accent via box-shadow (no layout shift).
   * Smooth transition — slides in, doesn't snap.
   */
  .spec-table tbody tr {
    transition: background 0.18s ease, box-shadow 0.18s ease;
  }

  .spec-table tbody tr:hover {
    background: #f2f2f2;
    box-shadow: inset 3px 0 0 #000;
  }

  .spec-table tbody tr:hover td { color: #000; }

  /*
   * LAST ROW
   * Remove dangling bottom border — table closes cleanly.
   */
  .spec-table tbody tr:last-child td { border-bottom: none; }

  /*
   * FOOTNOTE
   * Replaced inline style with class. Lightened and tightened —
   * supporting text, not competing text.
   */
  .spec-table-footnote {
    margin-top: 16px;
    font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 11px;
    line-height: 1.6;
    color: #888;
    letter-spacing: 0.03em;
  }

  /*
   * RESPONSIVE BREAKPOINT
   * Reduced padding and tracking at mobile so columns stay visible longer.
   */
  @media (max-width: 768px) {
    .spec-table th,
    .spec-table td {
      padding: 11px 12px;
      font-size: 11px;
    }

    .spec-table th {
      font-size: 9px;
      letter-spacing: 0.09em;
    }

    .spec-table td:first-child,
    .spec-table th:first-child { padding-left: 14px; }

    .spec-table td:last-child,
    .spec-table th:last-child  { padding-right: 14px; }
  }
</style>

<div class="spec-table-wrapper">
  <table class="spec-table">
    <thead>
      <tr>
        <th>Loft</th>
        <th>Hand</th>
        <th>Lie</th>
        <th>Volume</th>
        <th>Length*</th>
        <th>Swing Weight</th>
      </tr>
    </thead>
    <tbody>
      {% for row in spec_table.rows.value %}
        <tr>
          <td>{{ row.loft }}</td>
          <td>{{ row.hand }}</td>
          <td>{{ row.lie }}</td>
          <td>{{ row.volume }}</td>
          <td>{{ row.length }}</td>
          <td>{{ row.swing_weight }}</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>
  {% if spec_table.footnote != blank %}
    <div class="spec-table-footnote">
      {{ spec_table.footnote }}
    </div>
  {% endif %}
</div>
{% endif %}

