      display: block;
    }

    /*
     * IMAGE CAPTION
     * Matches title tracking and case — cohesive typographic system.
     */
    .grip-specs__caption {
      margin-top: 12px;
      text-align: center;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-size: 10px;
      color: #999;
    }

    /*
     * RESPONSIVE BREAKPOINT
     * Reduced padding and tracking at mobile so columns stay visible longer.
     */
    @media (max-width: 768px) {
      .grip-specs th,
      .grip-specs td {
        padding: 11px 12px;
        font-size: 11px;
      }

      .grip-specs th {
        font-size: 9px;
        letter-spacing: 0.09em;
      }

      .grip-specs td:first-child,
      .grip-specs th:first-child { padding-left: 14px; }

      .grip-specs td:last-child,
      .grip-specs th:last-child  { padding-right: 14px; }
    }
  </style>

  {% for grip_table in grip_tables %}
    <section class="grip-specs">
      {% assign table_title = grip_table.title | default: grip_table.grip | default: grip_table.name %}
      {% if table_title != blank %}
        <h2 class="grip-specs__title">{{ table_title }}</h2>
      {% endif %}
      <div class="grip-specs__table-wrap">
        <table>
          <thead>
            <tr>
              <th>Size</th>
              <th>Core</th>
              <th>Weight</th>
            </tr>
          </thead>
          <tbody>
            {% for row in grip_table.rows.value %}
              <tr>
                <td>{{ row.size }}</td>
                <td>{{ row.core }}</td>
                <td>{{ row.weight }}</td>
              </tr>
            {% endfor %}
          </tbody>
        </table>
        {% if grip_table.footnote != blank %}
          <div class="grip-specs__footnote">{{ grip_table.footnote }}</div>
        {% endif %}
      </div>
      {% if grip_table.image %}
        <div class="grip-specs__media">
          <div class="grip-specs__image-wrap">
            {{ grip_table.image
              | image_url: width: 1400
              | image_tag: loading: 'lazy', alt: table_title, class: 'grip-specs__image'
            }}
          </div>
          {% if grip_table.image_caption != blank %}
            <div class="grip-specs__caption">{{ grip_table.image_caption }}</div>
          {% endif %}
        </div>
      {% endif %}
    </section>
  {% endfor %}
{% endif %}
